function validate([board]) {
  if (!Array.isArray(board) || board.length < 2 || board.length > 30) return 'board needs 2 to 30 rows.';
  const n = board.length;
  for (const row of board) {
    if (!Array.isArray(row) || row.length !== n) return 'board must be square.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

