function movesToChessboard(board) {
  const n = board.length;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) === 1) {
        return -1;
      }
    }
  }
  let firstRowOnes = 0;
  let firstColOnes = 0;
  let rowDiff = 0;
  let colDiff = 0;
  for (let i = 0; i < n; i++) {
    firstRowOnes += board[0][i];
    firstColOnes += board[i][0];
    if (board[i][0] !== i % 2) {
      rowDiff++;
    }
    if (board[0][i] !== i % 2) {
      colDiff++;
    }
  }
  const low = Math.floor(n / 2);
  const high = Math.ceil(n / 2);
  if (firstRowOnes !== low && firstRowOnes !== high) {
    return -1;
  }
  if (firstColOnes !== low && firstColOnes !== high) {
    return -1;
  }
  if (n % 2 === 1) {
    if (rowDiff % 2 === 1) {
      rowDiff = n - rowDiff;
    }
    if (colDiff % 2 === 1) {
      colDiff = n - colDiff;
    }
  } else {
    rowDiff = Math.min(rowDiff, n - rowDiff);
    colDiff = Math.min(colDiff, n - colDiff);
  }
  return (rowDiff + colDiff) / 2;
}

