function movesToChessboard(board) {
  // Breadth-first search over every board reachable by row and column swaps.
  const n = board.length;
  const isChess = (b) => b.every((row, i) => row.every((v, j) => (j + 1 >= n || v !== row[j + 1]) && (i + 1 >= n || v !== b[i + 1][j])));
  const key = (b) => b.map(row => row.join('')).join('/');
  let frontier = [board.map(row => [...row])];
  const seen = new Set([key(board)]);
  for (let moves = 0; frontier.length > 0; moves++) {
    const next = [];
    for (const b of frontier) {
      if (isChess(b)) return moves;
      for (let a = 0; a < n; a++) {
        for (let c = a + 1; c < n; c++) {
          const rowSwap = b.map(row => [...row]);
          [rowSwap[a], rowSwap[c]] = [rowSwap[c], rowSwap[a]];
          const colSwap = b.map(row => { const copy = [...row]; [copy[a], copy[c]] = [copy[c], copy[a]]; return copy; });
          for (const candidate of [rowSwap, colSwap]) {
            const k = key(candidate);
            if (!seen.has(k)) { seen.add(k); next.push(candidate); }
          }
        }
      }
    }
    frontier = next;
  }
  return -1;
}

