function generate(rand, size) {
  const pick = (m) => Math.floor(rand() * m);
  const n = size === 'large' ? 24 + pick(7) : 2 + pick(rand() < 0.75 ? 3 : 4);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = pick(i + 1);
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  const mode = rand();
  if (mode < 0.15) {
    return [Array.from({ length: n }, () => Array.from({ length: n }, () => pick(2)))];
  }
  if (mode < 0.35) {
    // Every row equals a base row or its complement, but the counts may be unbalanced.
    const base = Array.from({ length: n }, () => pick(2));
    return [Array.from({ length: n }, () => (rand() < 0.5 ? [...base] : base.map(v => 1 - v)))];
  }
  // Shuffle the rows and columns of a real chessboard, so the answer is reachable.
  const corner = pick(2);
  const rows = shuffle(Array.from({ length: n }, (_, i) => i));
  const cols = shuffle(Array.from({ length: n }, (_, j) => j));
  const board = rows.map(r => cols.map(c => (corner + r + c) % 2));
  if (mode < 0.45) {
    const i = pick(n);
    const j = pick(n);
    board[i][j] = 1 - board[i][j];
  }
  return [board];
}
